from scipy.optimize import minimize
y=dP_dt
def build(b,c):
    base=[P**b*np.exp(c*t),P,P**2,t*P,t*P**2,t*P**b,np.ones_like(t),t,P**3]
    return np.c_[base].T
def loss(z):
    A=build(z[0],z[1])
    cc,_,_,_=np.linalg.lstsq(A,y,rcond=None)
    return np.var(A@cc-y)/np.var(y)
